#include "feature_advanced_symbols.hpp"
#include <windows.h>
#include <algorithm>
#include <fstream>
#include <iostream>
using namespace scratcher;
namespace {
int checks=0;
void check(bool condition,const char* message){++checks;if(!condition)throw std::runtime_error(message);}
template<class F>void rejects(F f,const char* message){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}check(rejected,message);}
using Bytes=std::vector<uint8_t>;
void integer(Bytes& b,uint64_t value,size_t width){for(size_t i=0;i<width;++i)b.push_back(static_cast<uint8_t>(value>>(i*8)));}
void put(Bytes& b,size_t offset,uint64_t value,size_t width){for(size_t i=0;i<width;++i)b.at(offset+i)=static_cast<uint8_t>(value>>(i*8));}
void text(Bytes& b,const std::string& value){b.insert(b.end(),value.begin(),value.end());b.push_back(0);}
void write(const std::filesystem::path& path,const Bytes& b){std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(b.data()),b.size());if(!out)throw std::runtime_error("Cannot write symbol fixture");}
Bytes dwarfElf(uint16_t version=4){
 Bytes abbrev={1,0x11,1,0,0,2,0x2e,0,3,8,0x11,1,0x12,6,0,0,0};
 Bytes body;integer(body,version,2);integer(body,0,4);integer(body,8,1);body.push_back(1);body.push_back(2);text(body,"dwarf_named_add");integer(body,0x401000,8);integer(body,6,4);body.push_back(0);Bytes info;integer(info,body.size(),4);info.insert(info.end(),body.begin(),body.end());
 Bytes header={1,1,1,static_cast<uint8_t>(-5),14,13,0,1,1,1,1,0,0,0,1,0,0,1};text(header,"fixture-src");header.push_back(0);text(header,"named.cpp");header.insert(header.end(),{1,0,0,0});
 Bytes program={0,9,2};integer(program,0x401000,8);program.insert(program.end(),{3,9,1,2,6,0,1,1});Bytes lineBody;integer(lineBody,4,2);integer(lineBody,header.size(),4);lineBody.insert(lineBody.end(),header.begin(),header.end());lineBody.insert(lineBody.end(),program.begin(),program.end());Bytes lines;integer(lines,lineBody.size(),4);lines.insert(lines.end(),lineBody.begin(),lineBody.end());
 std::vector<std::pair<std::string,Bytes>> sections={{"",{}},{".text",{0x89,0xf8,0x83,0xc0,1,0xc3,0x90,0xc3}},{".debug_info",info},{".debug_abbrev",abbrev},{".debug_line",lines},{".shstrtab",{}}};Bytes names;std::vector<size_t> nameOffsets;for(auto& s:sections){nameOffsets.push_back(names.size());text(names,s.first);}sections.back().second=names;
 Bytes out(0x200);out[0]=0x7f;out[1]='E';out[2]='L';out[3]='F';out[4]=2;out[5]=1;out[6]=1;put(out,16,2,2);put(out,18,62,2);put(out,20,1,4);put(out,24,0x401000,8);put(out,32,64,8);put(out,52,64,2);put(out,54,56,2);put(out,56,1,2);put(out,58,64,2);put(out,60,sections.size(),2);put(out,62,sections.size()-1,2);put(out,64,1,4);put(out,68,5,4);put(out,72,0x200,8);put(out,80,0x401000,8);put(out,96,8,8);put(out,104,8,8);put(out,112,0x1000,8);
 std::vector<size_t> offsets;for(auto& s:sections){offsets.push_back(out.size());out.insert(out.end(),s.second.begin(),s.second.end());}while(out.size()%8)out.push_back(0);auto sh=out.size();put(out,40,sh,8);out.resize(out.size()+sections.size()*64);for(size_t i=1;i<sections.size();++i){auto offset=sh+i*64;put(out,offset,nameOffsets[i],4);put(out,offset+4,i==sections.size()-1?3:1,4);put(out,offset+8,i==1?6:0,8);put(out,offset+16,i==1?0x401000:0,8);put(out,offset+24,offsets[i],8);put(out,offset+32,sections[i].second.size(),8);put(out,offset+48,1,8);}return out;
}
}
__declspec(noinline) int symbols_test_named_function(int value){return value*7+3;}
int main(){try{
 auto dir=executableDir()/("symbols-fixtures-"+std::to_string(GetCurrentProcessId()));std::filesystem::create_directories(dir);auto raw=dir/"map.bin";write(raw,Bytes(64,0xc3));Engine engine;engine.open(raw);auto map=dir/"names.map";{std::ofstream out(map);out<<"0000000000001000 T mapped_start\n0000000000001010 T mapped_second\n";}
 auto imported=callSymbolsTool(engine,"load_debug_symbols",{{"path",pathText(map)},{"format","map"}}).value();check(imported["symbols"]==2,"map imports two functions");check(engine.binary()->functions[0].name=="mapped_start","map updates actual function name");auto listing=callSymbolsTool(engine,"list_debug_symbols",{{"query","second"},{"limit",1}}).value();check(listing["total"]==1&&listing["items"][0]["address"]=="0x1010","symbol pagination/filter");auto state=engine.advancedState();{std::ofstream out(map);out<<"ffff0000 T wrong_binary\n";}rejects([&]{callSymbolsTool(engine,"load_debug_symbols",{{"path",pathText(map)},{"format","map"}});},"outside map address rejected");check(engine.advancedState()==state,"failed import preserves state");check(callSymbolsTool(engine,"lookup_source_line",{{"address","0x1000"}})->at("found")==false,"map has no source lines");
 auto elf=dir/"dwarf.elf";write(elf,dwarfElf());engine.open(elf);imported=callSymbolsTool(engine,"load_debug_symbols",{{"format","dwarf"}}).value();check(imported["symbols"]==1,"DWARF subprogram imported");check(engine.binary()->functions[0].name=="dwarf_named_add"&&engine.binary()->functions[0].end==0x401006,"DWARF name and high-PC relative range");auto source=callSymbolsTool(engine,"lookup_source_line",{{"address","0x401003"}}).value();check(source["found"]==true&&source["line"]==10,"DWARF line state machine");check(source["file"].get<std::string>().find("named.cpp")!=std::string::npos,"DWARF source file");check(!callSymbolsTool(engine,"lookup_source_line",{{"address","0x401006"}})->at("found").get<bool>(),"end-sequence excludes next byte");auto saved=engine.advancedState();engine.advancedState()=saved;check(callSymbolsTool(engine,"lookup_source_line",{{"address","0x401000"}})->at("line")==10,"persisted source lookup needs no live reader");
 auto unsupported=dir/"dwarf5.elf";write(unsupported,dwarfElf(5));engine.open(unsupported);rejects([&]{callSymbolsTool(engine,"load_debug_symbols",{{"format","dwarf"}});},"DWARF5 explicitly rejected");auto truncated=dwarfElf();truncated.resize(0x204);auto broken=dir/"truncated.elf";write(broken,truncated);rejects([&]{engine.open(broken);callSymbolsTool(engine,"load_debug_symbols",{{"format","dwarf"}});},"truncated ELF debug sections rejected");
 wchar_t exeBuffer[32768]{};GetModuleFileNameW(nullptr,exeBuffer,32768);std::filesystem::path exe(exeBuffer),pdb=exe;pdb.replace_extension(L".pdb");check(std::filesystem::exists(pdb),"test target must build with /Zi and /DEBUG");engine.open(exe);imported=callSymbolsTool(engine,"load_debug_symbols",{{"path",pathText(pdb)},{"format","pdb"}}).value();check(imported["identity_verified"]==true&&imported["symbols"].get<size_t>()>0,"real matching PDB imported");listing=callSymbolsTool(engine,"list_debug_symbols",{{"query","symbols_test_named_function"}}).value();check(listing["total"].get<size_t>()>=1,"named test function resolved through PDB");auto target=listing["items"][0]["address"];source=callSymbolsTool(engine,"lookup_source_line",{{"address",target}}).value();check(source["found"]==true&&source["file"].get<std::string>().find("advanced_symbols_tests.cpp")!=std::string::npos,"PDB source line imported");
 Bytes changed;{std::ifstream in(exe,std::ios::binary);changed.assign(std::istreambuf_iterator<char>(in),{});}const Bytes rsds={'R','S','D','S'};auto reverse=std::search(changed.rbegin(),changed.rend(),rsds.rbegin(),rsds.rend());auto signature=reverse==changed.rend()?changed.end():reverse.base()-4;check(signature!=changed.end()&&changed.end()-signature>=24,"compiled fixture RSDS identity");signature[4]^=0x55;auto wrong=dir/"wrong.exe";write(wrong,changed);engine.open(wrong);rejects([&]{callSymbolsTool(engine,"load_debug_symbols",{{"path",pathText(pdb)},{"format","pdb"}});},"wrong binary PDB GUID rejected");check(engine.advancedState().empty(),"mismatched PDB import changes nothing");
 check(!callSymbolsTool(engine,"not_a_symbols_tool",{}).has_value(),"unrelated tool dispatch ignored");check(symbols_test_named_function(2)==17,"fixture code retained");std::cout<<checks<<" symbol checks passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
